195		@Override
196		public DeliveryProcessTaskForPcDTO queryTasksForPc (
197				DeliveryProcessQueryTaskForPcParam deliveryProcessQueryTaskForPcParam) {
198			String projectOrderId = deliveryProcessQueryTaskForPcParam.getProjectOrderId();
199			Boolean isExport = deliveryProcessQueryTaskForPcParam.getIsExport();
200			DeliveryProcess deliveryProcess = deliveryProcessMvcRepository.queryByProjectOrderId(projectOrderId);
201			if (deliveryProcess == null) {
202				return null;
203			}
204			List<DeliveryProcessTaskObj> deliveryProcessTaskObjs = deliveryProcessMvcRepository
205					.queryTasksByProjectOrderId(projectOrderId);
206			if (CollectionUtils.isEmpty(deliveryProcessTaskObjs)) {
207				return null;
208			}
209			log.info("queryTasksForPc,param：{}, 查询任务列表:{}", JsonUtils.obj2JsonStr(deliveryProcessQueryTaskForPcParam),
210					JsonUtils.obj2JsonStr(deliveryProcessTaskObjs));
211			List<DeliveryProcessTaskPoolCfg> deliveryProcessTaskPoolCfgs = deliveryProcessTaskPoolCfgMvcRepository
212					.queryAll();
213			// 顺序
214			Map<String, DeliveryProcessTaskPoolCfg> deliveryProcessTaskPoolCfgMap = deliveryProcessTaskPoolCfgs.stream()
215					.collect(Collectors.toMap(DeliveryProcessTaskPoolCfg::getTaskType,
216							deliveryProcessTaskPoolCfg -> deliveryProcessTaskPoolCfg, (k1, k2) -> k1));
217			List<DeliveryProcessTaskRelationObj> relationObjs = deliveryProcessMvcRepository
218					.queryTaskRelationsByProjectOrderIdAndType(projectOrderId,
219							DeliveryProcessTaskRelationTypeEnum.PLAN_PREDICT_RELATION.getCode());
220	
221			List<BusinessModelInterruptRecord> packageHangRecords = businessModelInterruptRecordMvcRepository
222					.queryByCondition(InterruptRecordQueryCondition.builder().projectOrderId(projectOrderId)
223							.type(BusinessModelInteruptTypeEnum.PACKAGE_HANGS.getCode()).build());
224	
225			Set<String> outTaskSet = relationObjs.stream()
226					.filter(relationObj -> InOutTypeEnum.OUT.getCode().equals(relationObj.getRelationNodeInOutType()))
227					.map(DeliveryProcessTaskRelationObj::getRelationCode).collect(Collectors.toSet());
228			// 日期切割 yyyy-MM-dd
229			this.cutTime(deliveryProcessTaskObjs);
230			// 根据查询条件过滤任务 除 nodeName外
231			List<DeliveryProcessTaskObj> filterTasks = deliveryProcessTaskHandle.filterTasks(
232					deliveryProcessQueryTaskForPcParam, deliveryProcessTaskObjs, deliveryProcess.getHolidayWork(),
233					outTaskSet);
234	
235			DeliveryProcessTaskForPcDTO deliveryProcessTaskForPcDTO = new DeliveryProcessTaskForPcDTO();
236			// 时间范围
237			deliveryProcessTaskForPcDTO.setDateRangeDTO(bulidDateRangeDTO(deliveryProcessTaskObjs, isExport));
238			deliveryProcessTaskForPcDTO.setDeliveryProcessTaskDetailDTOList(
239					buildDeliveryProcessTaskDetailDTOList(deliveryProcessTaskObjs, filterTasks, relationObjs,
240							deliveryProcess.getHolidayWork(), packageHangRecords, deliveryProcessTaskPoolCfgMap, isExport));
241			// 回填节点考核规则及取早取晚逻辑
242			fillAssessmentRuleList(deliveryProcessTaskForPcDTO.getDeliveryProcessTaskDetailDTOList(),
243					deliveryProcess.getTemplateSnapshotId());
244			deliveryProcessTaskForPcDTO
245					.setStopWorkDateRangeDTOList(bulidStopWorkRangeDTOList(deliveryProcess.getProjectOrderId()));
246			// 施工包增加上一级
247			deliveryProcessTaskHandle.handlePackageLevel(deliveryProcessTaskForPcDTO, packageHangRecords, filterTasks,
248					deliveryProcess.getHolidayWork());
249			// sort
250			List<DeliveryProcessTaskDetailDTO> deliveryProcessTaskDetailDTOList = deliveryProcessTaskForPcDTO
251					.getDeliveryProcessTaskDetailDTOList();
252			if (CollectionUtils.isNotEmpty(deliveryProcessTaskDetailDTOList)) {
253				// 过滤nodeName
254				deliveryProcessTaskDetailDTOList = deliveryProcessTaskDetailDTOList.stream()
255						.filter(deliveryProcessTaskDetailDTO -> deliveryProcessTaskHandle.filterByNodeName(
256								deliveryProcessQueryTaskForPcParam.getNodeName(), deliveryProcessTaskDetailDTO))
257						.collect(Collectors.toList());
258				deliveryProcessTaskDetailDTOList.sort(Comparator.comparing(DeliveryProcessTaskDetailDTO::getPlanStartTime)
259						.thenComparing(DeliveryProcessTaskDetailDTO::getSort));
260				deliveryProcessTaskForPcDTO.setDeliveryProcessTaskDetailDTOList(deliveryProcessTaskDetailDTOList);
261			}
262			return deliveryProcessTaskForPcDTO;
263		}
264	
265		/**
266		 * 按订单模板快照回填任务的考核规则列表及多条件取早取晚逻辑
267		 */
268		private void fillAssessmentRuleList (List<DeliveryProcessTaskDetailDTO> deliveryProcessTaskDetailDTOList, Long templateId) {
269			if (CollectionUtils.isEmpty(deliveryProcessTaskDetailDTOList) || templateId == null) {
270				return;
271			}
272			// 模板快照下全部节点配置（取valueRetrievalLogic）与考核规则
273			List<ProcessNodeCfg> processNodeCfgList = processNodeCfgMvcRepository.queryProcessNodeCfgList(templateId);
274			List<NodeAssessmentRuleCfg> nodeAssessmentRuleCfgList = nodeAssessmentRuleMVCRepository
275					.getByTemplateId(templateId);
276			if (CollectionUtils.isEmpty(nodeAssessmentRuleCfgList)) {
277				return;
278			}
279			// key=nodeCode+supplierCode+deliveryType
280			Map<String, Byte> cfgMap = processNodeCfgList.stream()
281					.collect(Collectors.toMap(cfg -> ProcessTaskAndMaterialTaskUtil.buildKey(cfg.getNodeCode(),
282							cfg.getSupplierCode(), cfg.getDeliveryType()), p -> p.getValueRetrievalLogic(), (a, b) -> a));
283			Map<String, List<NodeAssessmentRuleCfg>> assessmentRuleMap = nodeAssessmentRuleCfgList.stream()
284					.collect(Collectors.groupingBy(rule -> ProcessTaskAndMaterialTaskUtil.buildKey(rule.getNodeCode(),
285							rule.getSupplierCode(), rule.getDeliveryType())));
286			for (DeliveryProcessTaskDetailDTO dto : deliveryProcessTaskDetailDTOList) {
287				if (StringUtils.isBlank(dto.getNodeCode())) {
288					continue;
289				}
290				List<NodeAssessmentRuleCfg> rules = matchAssessmentRules(assessmentRuleMap, dto.getNodeCode(), dto.getSupplierCode(), dto.getDeliveryType());
291				if (CollectionUtils.isEmpty(rules)) {
292					continue;
293				}
294				// 取值逻辑优先按任务供应商取节点配置，取不到以不限供应商（9999999）取，仍取不到默认取晚
295				Byte valueRetrievalLogic = cfgMap.get(ProcessTaskAndMaterialTaskUtil.buildKey(
296						dto.getNodeCode(), dto.getSupplierCode(), dto.getDeliveryType()));
297				if (valueRetrievalLogic == null) {
298					valueRetrievalLogic = cfgMap.getOrDefault(ProcessTaskAndMaterialTaskUtil.buildKey(
299							dto.getNodeCode(), DeliveryProcessConstant.DEFAULT_SUPPLIER, dto.getDeliveryType()),
300							ValueRetrievalLogicEnum.LATEST.getCode().byteValue());
301				}
302				dto.setAssessmentRuleList(DeliveryProcessCfgTemplateTransfer
303						.transferNodeAssessmentRuleCfgDTOList(rules));
304				if (valueRetrievalLogic != null) {
305					dto.setValueRetrievalLogic(valueRetrievalLogic);
306				}
307			}
308		}
