310		/**
311		 * 优先按任务的供应商匹配考核规则，取不到再以不限供应商（9999999）取
312		 */
313		private List<NodeAssessmentRuleCfg> matchAssessmentRules (
314				Map<String, List<NodeAssessmentRuleCfg>> assessmentRuleMap, String nodeCode, String supplierCode,
315				Byte deliveryType) {
316			List<NodeAssessmentRuleCfg> rules = assessmentRuleMap.getOrDefault(ProcessTaskAndMaterialTaskUtil.buildKey(
317					nodeCode, supplierCode, deliveryType), Collections.emptyList());
318			if (CollectionUtils.isEmpty(rules)) {
319				rules = assessmentRuleMap.getOrDefault(ProcessTaskAndMaterialTaskUtil.buildKey(
320						nodeCode, DeliveryProcessConstant.DEFAULT_SUPPLIER, deliveryType), Collections.emptyList());
321			}
322			return rules;
323		}
