385		private void generateDiagnosisData (List<DeliveryProcessTaskDetailDTO> deliveryProcessTaskDetailDTOList) {
386			String today = DateUtil.formatToDay(new Date());
387			for (DeliveryProcessTaskDetailDTO dto : deliveryProcessTaskDetailDTOList) {
388				Map<Integer, DeliveryProcessBaseTimeDTO> timeMap = dto.getBaseTimeDTOList() != null
389						? dto.getBaseTimeDTOList().stream().collect(Collectors.toMap(DeliveryProcessBaseTimeDTO::getTimeType, t -> t, (t1, t2) -> t1))
390						: new HashMap<>();
391				DeliveryProcessBaseTimeDTO planTime = timeMap.get(TaskTimeTypeEnum.PLAN_TIME.getValue());
392				DeliveryProcessBaseTimeDTO factTime = timeMap.get(TaskTimeTypeEnum.FACT_TIME.getValue());
393				DeliveryProcessBaseTimeDTO assessmentTime = timeMap.get(TaskTimeTypeEnum.ASSESSMENT_TIME.getValue());
394				Integer status = dto.getStatus();
395				//1. currentNodePlanDelayDTO 计划延期
396				DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO planDelayDTO = buildPlanDelayDTO(status, planTime, factTime, assessmentTime, today);
397				dto.setCurrentNodePlanDelayDTO(planDelayDTO);
398				//2. currentNodeAssessmentDelayDTO 考核延期
399				DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO assessmentDelayDTO = buildAssessmentDelayDTO(status, planTime, factTime, assessmentTime, today);
400				dto.setCurrentNodeAssessmentDelayDTO(assessmentDelayDTO);
401				//3. currentDelayIsRootCause 根因判定
402				//不是根因：考核开始时间<=计划开始时间，且 已完成时实际完成时间<=考核完成时间，未完成时考核完成时间>=计划完成时间；其余为根因
403				dto.setDelayIsSelfReason(isRootCause(status, planTime, factTime, assessmentTime));
404			}
405		}
