407		private boolean isRootCause (Integer status, DeliveryProcessBaseTimeDTO planTime, DeliveryProcessBaseTimeDTO factTime, DeliveryProcessBaseTimeDTO assessmentTime) {
408			if (assessmentTime == null || StringUtils.isBlank(assessmentTime.getStartDate())) {
409				return false;
410			}
411			String today = DateUtil.formatToDay(new Date());
412			//不是自身原因：考核开始时间<=计划开始时间，且 已完成时实际完成时间<=考核完成时间，未完成时考核完成时间>=计划完成时间；其余为根因
413			String assessmentStartTime = assessmentTime.getStartDate();
414			String assessmentEndTime = assessmentTime.getEndDate();
415			String planStartTime = planTime != null ? planTime.getStartDate() : null;
416			String planEndTime = planTime != null ? planTime.getEndDate() : null;
417			//不是根因条件：考核开始时间<=计划开始时间
418			/*boolean assessmentStartOnTime = planStartTime != null && assessmentStartTime.compareTo(planStartTime) <= 0;
419			if (assessmentStartOnTime) {
420				return true;
421			}*/
422			//不是根因条件补充：已完成时实际完成时间<=考核完成时间，未完成时考核完成时间>=计划完成时间
423			if (DeliveryProcessTaskStatusEnum.COMPLETE.getCode().equals(status)) {
424				String factEndTime = factTime != null ? factTime.getEndDate() : null;
425				if ((!DateUtil.DEFAULT_DATE_MIN.equals(assessmentEndTime)) && factEndTime != null && factEndTime.compareTo(assessmentEndTime) > 0) {
426					return true;
427				}
428			} else {
429				//未完成（待开始/进行中/未完成）
430				if ((!DateUtil.DEFAULT_DATE_MIN.equals(assessmentEndTime) && !DateUtil.DEFAULT_DATE_MIN.equals(assessmentStartTime) && (assessmentStartTime.compareTo(planStartTime) <= 0 || assessmentEndTime.compareTo(planEndTime) > 0)) || (!DateUtil.DEFAULT_DATE_MIN.equals(assessmentEndTime) && !DateUtil.DEFAULT_DATE_MIN.equals(assessmentStartTime) && (today.compareTo(assessmentStartTime) > 0 || today.compareTo(assessmentEndTime) > 0))) {
431					return true;
432				}
433			}
434			return false;
435		}
