437		private DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO buildPlanDelayDTO (Integer status, DeliveryProcessBaseTimeDTO planTime, DeliveryProcessBaseTimeDTO factTime, DeliveryProcessBaseTimeDTO assessmentTime, String today) {
438			if (planTime == null || StringUtils.isBlank(planTime.getEndDate())) {
439				return null;
440			}
441			String planEndTime = planTime.getEndDate();
442			//未完成的任务：看计划结束时间和考核结束时间对比，和当前时间对比，取长的延期时间
443			if (DeliveryProcessTaskStatusEnum.WAIT_START.getCode().equals(status)
444					|| DeliveryProcessTaskStatusEnum.DOING.getCode().equals(status)
445					|| DeliveryProcessTaskStatusEnum.UN_COMPLETE.getCode().equals(status)) {
446				String compareTime = today;
447				if (assessmentTime != null && StringUtils.isNotBlank(assessmentTime.getEndDate()) && !DateUtil.DEFAULT_DATE_MIN.equals(assessmentTime.getEndDate())
448						&& assessmentTime.getEndDate().compareTo(today) > 0) {
449					compareTime = assessmentTime.getEndDate();
450				}
451				return buildDelayDTO(planEndTime, compareTime);
452			}
453			//已完成的任务：计划和实际完成时间对比
454			if (DeliveryProcessTaskStatusEnum.COMPLETE.getCode().equals(status)) {
455				if (factTime == null || StringUtils.isBlank(factTime.getEndDate())) {
456					return null;
457				}
458				return buildDelayDTO(planEndTime, factTime.getEndDate());
459			}
460			return null;
461		}
