463		private DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO buildAssessmentDelayDTO (Integer status, DeliveryProcessBaseTimeDTO planTime, DeliveryProcessBaseTimeDTO factTime, DeliveryProcessBaseTimeDTO assessmentTime, String today) {
464			if (assessmentTime == null || StringUtils.isBlank(assessmentTime.getStartDate())) {
465				return null;
466			}
467			String assessmentStartTime = assessmentTime.getStartDate();
468			String assessmentEndTime = assessmentTime.getEndDate();
469			boolean isDelay = false;
470			Integer delayDay = 0;
471			String delayStart = null;
472			String delayEnd = null;
473			if (DeliveryProcessTaskStatusEnum.WAIT_START.getCode().equals(status)) {
474				//未开始：考核开始 > 计划开始 || 当前时间 > 考核开始时间
475				String planStartTime = planTime != null ? planTime.getStartDate() : null;
476				boolean cond1 = planStartTime != null && assessmentStartTime.compareTo(planStartTime) > 0;
477				boolean cond2 = !DateUtil.DEFAULT_DATE_MIN.equals(assessmentStartTime) && today.compareTo(assessmentStartTime) > 0;
478				isDelay = cond1 || cond2;
479				if (isDelay) {
480					try {
481						int delay1 = cond1 ? (int) DateUtil.distancebetweenDate(planStartTime, assessmentStartTime) : 0;
482						int delay2 = cond2 ? (int) DateUtil.distancebetweenDate(assessmentStartTime, today) : 0;
483						if (delay1 >= delay2) {
484							delayDay = delay1;
485							delayStart = planStartTime;
486							delayEnd = assessmentStartTime;
487						} else {
488							delayDay = delay2;
489							delayStart = assessmentStartTime;
490							delayEnd = today;
491						}
492					} catch (Exception e) {
493						log.error("计算考核延期天数异常, planStartTime:{}, assessmentStartTime:{}, today:{}",
494								planStartTime, assessmentStartTime, today, e);
495						return null;
496					}
497	
498				}
499			} else if (DeliveryProcessTaskStatusEnum.DOING.getCode().equals(status)) {
500				//进行中：实际开始 > 考核开始 || 计划结束 < 考核结束 || 当前时间 > 考核结束
501				String factStartTime = factTime != null ? factTime.getStartDate() : null;
502				String planEndTime = planTime != null ? planTime.getEndDate() : null;
503				boolean cond1 = !DateUtil.DEFAULT_DATE_MIN.equals(assessmentStartTime) && factStartTime != null && factStartTime.compareTo(assessmentStartTime) > 0;
504				boolean cond2 = !DateUtil.DEFAULT_DATE_MIN.equals(assessmentStartTime) && planEndTime != null && StringUtils.isNotBlank(assessmentEndTime) && planEndTime.compareTo(assessmentEndTime) < 0;
505				boolean cond3 = !DateUtil.DEFAULT_DATE_MIN.equals(assessmentStartTime) && StringUtils.isNotBlank(assessmentEndTime) && today.compareTo(assessmentEndTime) > 0;
506				isDelay = cond1 || cond2 || cond3;
507				if (isDelay) {
508					try {
509						int delay1 = cond1 ? (int) DateUtil.distancebetweenDate(assessmentStartTime, factStartTime) : 0;
510						int delay2 = cond2 ? (int) DateUtil.distancebetweenDate(planEndTime, assessmentEndTime) : 0;
511						int delay3 = cond3 ? (int) DateUtil.distancebetweenDate(assessmentEndTime, today) : 0;
512						if (delay1 >= delay2 && delay1 >= delay3) {
513							delayDay = delay1;
514							delayStart = assessmentStartTime;
515							delayEnd = factStartTime;
516						} else if (delay2 >= delay1 && delay2 >= delay3) {
517							delayDay = delay2;
518							delayStart = planEndTime;
519							delayEnd = assessmentEndTime;
520						} else {
521							delayDay = delay3;
522							delayStart = assessmentEndTime;
523							delayEnd = today;
524						}
525					} catch (Exception e) {
526						log.error("计算考核延期天数异常, assessmentStartTime:{}, planEndTime:{}, assessmentEndTime:{}, today:{}",
527								assessmentStartTime, planEndTime, assessmentEndTime, today, e);
528						return null;
529					}
530	
531				}
532			} else if (DeliveryProcessTaskStatusEnum.COMPLETE.getCode().equals(status)) {
533				//已完成：实际开始 > 考核开始 || 实际结束 > 考核结束
534				String factStartTime = factTime != null ? factTime.getStartDate() : null;
535				String factEndTime = factTime != null ? factTime.getEndDate() : null;
536				boolean cond1 = factStartTime != null && factStartTime.compareTo(assessmentStartTime) > 0;
537				boolean cond2 = factEndTime != null && StringUtils.isNotBlank(assessmentEndTime) && factEndTime.compareTo(assessmentEndTime) > 0;
538				isDelay = cond1 || cond2;
539				if (isDelay) {
540					try {
541						int delay1 = cond1 ? (int) DateUtil.distancebetweenDate(assessmentStartTime, factStartTime) : 0;
542						int delay2 = cond2 ? (int) DateUtil.distancebetweenDate(assessmentEndTime, factEndTime) : 0;
543						if (delay1 >= delay2) {
544							delayDay = delay1;
545							delayStart = assessmentStartTime;
546							delayEnd = factStartTime;
547						} else {
548							delayDay = delay2;
549							delayStart = assessmentEndTime;
550							delayEnd = factEndTime;
551						}
552					} catch (Exception e) {
553						log.error("计算考核延期天数异常, assessmentStartTime:{}, assessmentEndTime:{}, factStartTime:{}, factEndTime:{}",
554								assessmentStartTime, assessmentEndTime, factStartTime, factEndTime, e);
555						return null;
556					}
557	
558				}
559			}
560			if (!isDelay) {
561				return buildOnTimeDelayDTO(assessmentTime);
562			}
563			int workDays = 0;
564			if (delayDay > 0 && delayStart != null && delayEnd != null) {
565				workDays = bimScheduleAlgorithmUtil.getWorkdayForCalculateDelay(delayStart, delayEnd, WorkTypeEnum.WORKDAY.getValue()).intValue();
566			}
567			DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO delayDTO = new DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO();
568			delayDTO.setOnTimeStatus(TaskOnTimeStatusEnum.DELAY.getCode());
569			delayDTO.setDurationInNaturalDays(delayDay);
570			delayDTO.setDurationInWorkDays(workDays);
571			return delayDTO;
572		}
