574		private DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO buildDelayDTO (String startTime, String endTime) {
575			if (StringUtils.isBlank(startTime) || StringUtils.isBlank(endTime)) {
576				return null;
577			}
578			int onTimeStatus;
579			int naturalDays;
580			int workDays = 0;
581			try {
582				if (endTime.compareTo(startTime) > 0) {
583					onTimeStatus = TaskOnTimeStatusEnum.DELAY.getCode();
584					naturalDays = (int) DateUtil.distancebetweenDate(startTime, endTime);
585				} else if (endTime.compareTo(startTime) < 0) {
586					onTimeStatus = TaskOnTimeStatusEnum.AHEAD.getCode();
587					naturalDays = (int) DateUtil.distancebetweenDate(endTime, startTime);
588				} else {
589					onTimeStatus = TaskOnTimeStatusEnum.ON_TIME.getCode();
590					naturalDays = 0;
591				}
592				if (naturalDays > 0) {
593					String earlier = endTime.compareTo(startTime) > 0 ? startTime : endTime;
594					String later = endTime.compareTo(startTime) > 0 ? endTime : startTime;
595					workDays = bimScheduleAlgorithmUtil.getWorkdayForCalculateDelay(earlier, later, WorkTypeEnum.WORKDAY.getValue()).intValue();
596				}
597			} catch (Exception e) {
598				log.error("计算延期天数异常, startTime:{}, endTime:{}", startTime, endTime, e);
599				return null;
600			}
601			DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO delayDTO = new DeliveryProcessTaskDetailDTO.CurrentNodeDelayDTO();
602			delayDTO.setOnTimeStatus(onTimeStatus);
603			delayDTO.setDurationInNaturalDays(naturalDays);
604			delayDTO.setDurationInWorkDays(workDays);
605			return delayDTO;
606		}
