610			delayDTO.setOnTimeStatus(TaskOnTimeStatusEnum.ON_TIME.getCode());
611			delayDTO.setDurationInNaturalDays(0);
612			delayDTO.setDurationInWorkDays(0);
613			return delayDTO;
