729		@Override
730		public DeliveryProcessInfoDTO queryProcessBaseInfo (Long projectOrderId) {
731			// 详情(查全交付流程数据)
732			DeliveryProcess deliveryProcess = deliveryProcessMvcRepository
733					.queryByProjectOrderId(String.valueOf(projectOrderId));
734			if (Objects.isNull(deliveryProcess)) {
735				log.info("DeliveryProcessQueryServiceImpl.deliveryProcess deliveryProcess is null! projectOrderId:{}",
736						projectOrderId);
737				return null;
738			}
739	
740			// 1. 获取流程基础信息
741			DeliveryProcessBasicInfoDTO processBasicInfoDTO = this.getProcessBasicInfoDTO(deliveryProcess.getHomeOrderNo(), projectOrderId,
742					deliveryProcess.getHolidayWork());
743			// 2 补充流程数据
744			processBasicInfoDTO.setDeliveryProcessId(deliveryProcess.getId());
745			processBasicInfoDTO.setDeliveryProcessStatus(deliveryProcess.getStatus());
746			if (DeliveryProcessStatusEnum.CANCEL.getCode().equals(deliveryProcess.getStatus())) {
747				String cancelDate = DateUtil.format(deliveryProcess.getMtime(), DateUtil.DEFAULT_DAY_FORMAT);
748				processBasicInfoDTO.setCancelDate(cancelDate);
749			}
750			List<DeliveryProcessTaskObj> taskObjs = deliveryProcessMvcRepository
751					.queryTasksByProjectOrderId(String.valueOf(projectOrderId));
752			taskObjs = deliveryProcessTaskHandle.filterRestartedNode(taskObjs);
753			this.cutTime(taskObjs);
754			// 计算总工期延期/提前天数
755			DateIntervalDTO dateIntervalDTO = deliveryProcessTaskHandle.buildProcessDateIntervalDTO(deliveryProcess,
756					taskObjs);
757			List<DeliveryProcessBaseTimeDTO> deliveryProcessBaseTimeDTOS = deliveryProcessTaskHandle
758					.listProcessBaseTimeDTO(deliveryProcess, taskObjs);
759			processBasicInfoDTO.setProcessDateIntervalDTO(dateIntervalDTO);
760			processBasicInfoDTO.setProcessBaseTimeDTOList(deliveryProcessBaseTimeDTOS);
761			DeliveryProcessInfoDTO deliveryProcessInfoDTO = new DeliveryProcessInfoDTO();
762			deliveryProcessInfoDTO.setDeliveryProcessBasicInfoDTO(processBasicInfoDTO);
763	
764			// 3. 特殊节点数据
765			Set<String> nodeCodeSet = deliveryProcessNodeSortMap.keySet();
766			List<DeliveryProcessTaskObj> filterTasks = taskObjs.stream()
767					.filter(deliveryProcessTaskObj -> nodeCodeSet.contains(deliveryProcessTaskObj.getNodeCode()))
768					.collect(Collectors.toList());
