839		public List<DeliveryProcessTaskDetailDTO> queryProcessAlarmTasks (Long projectOrderId) {
840			// 1. 查所有未开始和进行中的任务
841			DeliveryProcess deliveryProcess = deliveryProcessMvcRepository
842					.queryByProjectOrderId(String.valueOf(projectOrderId));
843			if (Objects.isNull(deliveryProcess)) {
844				log.info(
845						"DeliveryProcessQueryServiceImpl.queryProcessAlarmTasks deliveryProcess is null! projectOrderId:{}",
846						projectOrderId);
847				return Collections.emptyList();
848			}
849			// 2. 查询任务并过滤
850			List<DeliveryProcessTaskObj> filterTaskObjs = this.listDeliveryTaskObjByOrder(String.valueOf(projectOrderId),
851					Lists.newArrayList(DeliveryProcessTaskStatusEnum.WAIT_START.getCode(),
852							DeliveryProcessTaskStatusEnum.DOING.getCode()));
853			if (CollectionUtils.isEmpty(filterTaskObjs)) {
854				return Collections.emptyList();
855			}
