859					.map(deliveryProcessTaskObj -> deliveryProcessTaskHandle.buildDeliveryProcessTaskDetailDTO(
860							deliveryProcessTaskObj, Collections.emptyList(), nodeCodeMap, deliveryProcess.getHolidayWork(),
861							new HashMap<>(), false))
862					.collect(Collectors.toList());
863	
864			// 3. 处理数据，排序 (待开始最多3个任务，进行中最多3个任务)
865			List<DeliveryProcessTaskDetailDTO> waitedTaskDetailDTOList = new ArrayList<>();
866			List<DeliveryProcessTaskDetailDTO> doingTaskDetailDTOList = new ArrayList<>();
867			taskDetailDTOList.stream()
868					.filter(dto -> Objects.nonNull(dto.getDateIntervalDTO())
869							&& TaskOnTimeStatusEnum.DELAY.getCode().equals(dto.getDateIntervalDTO().getOnTimeStatus()))
870					.forEach(dto -> {
