872							waitedTaskDetailDTOList.add(dto);
873						} else if (DeliveryProcessTaskStatusEnum.DOING.getCode().equals(dto.getStatus())) {
874							doingTaskDetailDTOList.add(dto);
875						}
876					});
877	
878			List<DeliveryProcessTaskDetailDTO> resultTaskDetailList = new ArrayList<>();
879			addTopNTasks(resultTaskDetailList, doingTaskDetailDTOList, deliveryProcessTaskHandle::sortDoingTask, 3);
880			addTopNTasks(resultTaskDetailList, waitedTaskDetailDTOList, deliveryProcessTaskHandle::sortWaitedTask, 3);
881			return resultTaskDetailList;
882		}
