931				for (DeliveryProcessTaskStatusDTO.DeliveryProcessSecondStatusDTO deliveryProcessSecondStatusDTO : deliveryProcessSecondStatusDTOList) {
932					Integer statusCode = deliveryProcessSecondStatusDTO.getStatusCode();
933					if (Objects.nonNull(secondStatusTaskCountMap.get(statusCode))) {
934						deliveryProcessSecondStatusDTO.setTaskNums(secondStatusTaskCountMap.get(statusCode));
