1076		/**
1077		 * 根据传入的nodeCode往后查找最近的验收节点
1078		 *
1079		 * @param packageStageQueryParam 参数
1080		 * @return 最近的验收节点编码列表
1081		 */
1082		@Override
1083		public Map<String, String> queryNextNearestAcceptanceByNodeCode (PackageStageQueryParam packageStageQueryParam) {
1084			List<String> packageCodes = packageStageQueryParam.getPackageCodes();
1085			String projectOrderId = packageStageQueryParam.getProjectOrderId();
1086			DeliveryProcess deliveryProcess = deliveryProcessMvcRepository.queryByProjectOrderId(projectOrderId);
1087			if (deliveryProcess == null) {
1088				log.info("queryNextNearestAcceptanceByNodeCode, projectOrderId: {}, deliveryProcess is null", projectOrderId);
1089				return null;
1090			}
1091			log.info("queryNextNearestAcceptanceByNodeCode, projectOrderId: {}, nodeCode: {}, deliveryProcess: {}",
1092					projectOrderId, packageCodes, JsonUtils.obj2JsonStr(deliveryProcess));
1093	
1094			//根据businessId + taskType 查找节点
1095			DeliveryProcessTaskQueryCondition deliveryProcessTaskQueryCondition = DeliveryProcessTaskQueryCondition
1096					.builder().projectOrderId(projectOrderId).businessIdList(packageCodes).taskType(DeliveryProcessTaskTypeConstant.BASE_CONSTRUCTION_WORK).build();
1097			List<DeliveryProcessTaskObj> deliveryProcessTaskObjs = deliveryProcessMvcRepository.listTaskByCondition(deliveryProcessTaskQueryCondition);
1098			if (CollectionUtils.isEmpty(deliveryProcessTaskObjs)) {
1099				log.info("queryNextNearestAcceptanceByNodeCode, projectOrderId: {},packageCode: {},  deliveryProcessTaskObjs is empty", projectOrderId, packageCodes);
1100				return null;
1101			}
1102			Set<String> nodeCodeSet = deliveryProcessTaskObjs.stream().map(DeliveryProcessTaskObj::getNodeCode).collect(Collectors.toSet());
1103			//nodeCode和 businessId的映射关系
1104			Map<String, String> nodeCodeBusinessIdMap = deliveryProcessTaskObjs.stream().collect(Collectors.toMap(DeliveryProcessTaskObj::getNodeCode, DeliveryProcessTaskObj::getBusinessId, (k1, k2) -> k1));
1105	
1106			DeliveryProcessCfg deliveryProcessCfg = deliveryProcessCfgMvcRepository.queryById(deliveryProcess.getDeliveryProcessCfgId());
1107			if (deliveryProcessCfg == null) {
1108				log.info("queryNextNearestAcceptanceByNodeCode, projectOrderId: {}, deliveryProcessCfg is null", projectOrderId);
1109				return null;
1110			}
1111	
1112			// 查询配置
1113			DeliveryProcessCfgTemplateEntity deliveryProcessCfgTemplateEntity = deliveryProcessCfgTemplateMvcRepository
1114					.buildConfigByTemplateIdWithoutSnapshot(
1115							deliveryProcess.getTemplateSnapshotId(),
1116							TaskPoolUtils.getSupportType(deliveryProcessCfg.getDecorateBusinessType(), deliveryProcessCfg.getFulfillmentMode()),
1117							deliveryProcessCfg.getId());
1118	
1119			if (deliveryProcessCfgTemplateEntity == null) {
1120				log.info("queryNextNearestAcceptanceByNodeCode, projectOrderId: {}, templateSnapshotId: {}, deliveryProcessCfgTemplateEntity is null",
1121						projectOrderId, deliveryProcess.getTemplateSnapshotId());
1122				return null;
1123			}
1124	
1125			// 边界值处理：如果传入的节点本身就是验收节点，直接返回
1126			nodeCodeSet = nodeCodeSet.stream().filter(nodeCode -> !DeliveryProcessTaskTypeConstant.NODE_ACCEPTACE_LIST.contains(nodeCode)).collect(Collectors.toSet());
1127			if (CollectionUtils.isEmpty(nodeCodeSet)) {
1128				log.info("queryNextNearestAcceptanceByNodeCode, 过滤后nodeCodes为空");
1129				return new HashMap<String, String>();
1130			}
1131	
1132			// 往后查找最近的一个验收节点，返回Map结构（key=nodeCode, value=最近的验收节点）
1133			Map<String, String> nextAcceptanceMap = DeliveryProcessNodePreCheckUtil.findNextNearestAcceptanceNode(
1134					nodeCodeSet,
1135					deliveryProcessCfgTemplateEntity.getProcessNodeCfgList(),
1136					deliveryProcessCfgTemplateEntity.getNodeRelationTimeRuleCfgDTOList(),
1137					DeliveryProcessTaskTypeConstant.NODE_ACCEPTACE_LIST);
1138	
1139			// 边界值处理：如果找不到后续验收节点，返回空列表
1140			//将 nextAcceptanceMap中的nodeCode替换成businessId返回
1141			nextAcceptanceMap = nextAcceptanceMap.entrySet().stream().collect(Collectors.toMap(entry -> nodeCodeBusinessIdMap.get(entry.getKey()), Map.Entry::getValue));
1142			return nextAcceptanceMap;
1143		}
