1413							return org.springframework.util.CollectionUtils.isEmpty(taskHandleRoleDTO.getHandleRoleList()) ? com.google.common.collect.Lists.newArrayList() : taskHandleRoleDTO.getHandleRoleList();
1414						}, (t1, t2) -> t1));
1415	
1416				Map<String, String> taskTypeUnifiedTaskTypeMap = list.stream().collect(Collectors.toMap(DeliveryProcessTaskPoolCfg::getTaskType, DeliveryProcessTaskPoolCfg::getUnifiedTaskType, (t1, t2) -> t1));
1417				List<ProjectProcessNodeDto> processNodeList = new ArrayList<>();
