179	    public List<FollowUpMaterialDTO> listConfiguredMaterials() {
180	        FollowUpConfig.FollowUpGenerateRuleBO rule = followUpConfig.getGenerateRule();
181	        if (rule == null || rule.getMaterialTaskTypes() == null || rule.getMaterialTaskTypes().isEmpty()) {
182	            return Collections.emptyList();
183	        }
184	        // 029 履约类目 code -> name
185	        Map<String, String> materialNameMap = new java.util.HashMap<>();
186	        List<MaterialDTO> materialList =
187	                scmProductReadRepository.queryMaterialList(categoryConfiguration);
188	        if (CollectionUtils.isEmpty(materialList)) {
189	            return Collections.emptyList();
190	        }
191	        materialList.forEach(m -> materialNameMap.put(m.getMaterialCode(), m.getMaterialName()));
192	        return rule.getMaterialTaskTypes().keySet().stream()
193	                .map(code -> FollowUpMaterialDTO.builder()
194	                        .code(code)
195	                        .name(materialNameMap.getOrDefault(code, code))
196	                        .build())
