200	    @Override
201	    public List<FollowUpRecordDTO> records(Long followUpTaskId) {
202	        List<FollowUpRecord> list = followUpRecordRepository.selectByFollowUpTaskIds(Collections.singletonList(followUpTaskId));
203	        if (CollectionUtils.isEmpty(list)) {
204	            return Collections.emptyList();
205	        }
206	        return list.stream().map(FollowUpTaskTransfer::convertRecord).collect(Collectors.toList());
207	    }
208	
209	    /**
210	     * 任务表无跟进时间列，从流水聚合：跟进记录挂到任务内，最近跟进时间=最新流水ctime，下次跟进时间=最新一次约跟进的next_follow_up_time
211	     */
212	    private void fillFollowUpRecords(List<FollowUpTaskDTO> dtoList) {
213	        if (CollectionUtils.isEmpty(dtoList)) {
214	            return;
215	        }
216	        List<Long> taskIds = dtoList.stream().map(FollowUpTaskDTO::getId).collect(Collectors.toList());
217	        List<FollowUpRecord> records = followUpRecordRepository.selectByFollowUpTaskIds(taskIds);
218	        if (CollectionUtils.isEmpty(records)) {
219	            return;
220	        }
221	        Map<Long, List<FollowUpRecord>> recordMap = records.stream()
222	                .collect(Collectors.groupingBy(FollowUpRecord::getFollowUpTaskId));
223	        for (FollowUpTaskDTO dto : dtoList) {
224	            List<FollowUpRecord> taskRecords = recordMap.get(dto.getId());
225	            if (CollectionUtils.isEmpty(taskRecords)) {
226	                continue;
227	            }
228	            dto.setRecords(taskRecords.stream().map(FollowUpTaskTransfer::convertRecord).collect(Collectors.toList()));
229	            // 记录按 id 倒序，最新一次约跟进（首条非空）即下次跟进时间
230	            taskRecords.stream()
231	                    .filter(record -> StringUtils.isNotBlank(record.getNextFollowUpTime()))
232	                    .findFirst()
233	                    .ifPresent(record -> dto.setNextFollowUpTime(record.getNextFollowUpTime()));
234	        }
235	    }
236	
237	    /**
238	     * 批量挂载订单信息：业主姓名/服务者(管家)/物业地址/订单阶段
239	     */
240	    private void fillOrderInfo(List<FollowUpTaskDTO> dtoList) {
241	        if (CollectionUtils.isEmpty(dtoList)) {
242	            return;
243	        }
244	        Set<Long> projectOrderIds = dtoList.stream()
245	                .map(FollowUpTaskDTO::getProjectOrderId)
246	                .filter(StringUtils::isNotBlank)
247	                .map(Long::valueOf)
248	                .collect(Collectors.toSet());
249	        if (CollectionUtils.isEmpty(projectOrderIds)) {
250	            return;
251	        }
252	        List<ProjectOrderObj> orderList = shuttleOrderRepository.getProjectDetails(projectOrderIds);
253	        if (CollectionUtils.isEmpty(orderList)) {
254	            return;
255	        }
256	        Map<Long, ProjectOrderObj> orderMap = orderList.stream()
257	                .filter(o -> o.getProjectOrderId() != null)
258	                .collect(Collectors.toMap(ProjectOrderObj::getProjectOrderId, o -> o, (a, b) -> a));
259	        for (FollowUpTaskDTO dto : dtoList) {
260	            if (StringUtils.isBlank(dto.getProjectOrderId())) {
261	                continue;
262	            }
263	            ProjectOrderObj order = orderMap.get(Long.valueOf(dto.getProjectOrderId()));
264	            if (order == null) {
265	                continue;
266	            }
267	            dto.setCustomerName(order.getHomeownerName());
268	            dto.setServers(FollowUpTaskTransfer.convertServers(order.getProjectServerBaseInfos()));
269	            dto.setHandlerName(matchHandlerName(dto.getHandlerRole(), order.getProjectServerBaseInfos()));
270	            dto.setHouseAddress(order.getOrderHouseDetailObj() == null ? null : order.getOrderHouseDetailObj().getAddress());
271	            dto.setOrderStage(order.getStatus());
272	            dto.setOrderStageDesc(order.getStatusStr());
273	        }
274	    }
275	
276	    /**
277	     * 按任务处理人角色匹配订单服务者，取姓名（逗号分隔）
278	     */
279	    private String matchHandlerName(String handlerRole, List<ProjectServerBaseInfoObj> serverBaseInfos) {
280	        if (StringUtils.isBlank(handlerRole) || CollectionUtils.isEmpty(serverBaseInfos)) {
281	            return null;
282	        }
283	        return java.util.Arrays.stream(handlerRole.split(","))
284	                .filter(StringUtils::isNotBlank)
285	                .map(String::trim)
286	                .map(role -> serverBaseInfos.stream()
287	                        .filter(s -> role.equalsIgnoreCase(s.getType()))
288	                        .findFirst()
289	                        .map(ProjectServerBaseInfoObj::getName)
290	                        .orElse(null))
291	                .filter(StringUtils::isNotBlank)
292	                .distinct()
293	                .collect(Collectors.joining(","));
294	    }
295	}
